if(sessionStorage.getItem('regwatch-demo-access')!=='granted')window.location.replace('index.html');
document.querySelector('#sign-out').addEventListener('click',()=>{sessionStorage.removeItem('regwatch-demo-access');sessionStorage.removeItem('regwatch-demo-email');window.location.replace('index.html')});
const fallback={publication_date:'2026-09-21',title:'Exchange Publishes Consultation Paper on Phase II of Listing Framework Competitiveness Review',official_url:'https://www.hkex.com.hk/News/Regulatory-Announcements/2026/260921news?sc_lang=en',source_id:'DEDUP-00033',source_label:'HKEX Regulatory Announcements',regulatory_domain:'listing_rules',change_type:'consultation_paper',impact_status:'potential_impact',summary:'HKEX is consulting on post-listing transaction, connected-transaction and spin-off requirements.',evidence:['Official source retained for review.'],human_review_required:true};
const detail=document.querySelector('#detail'),feed=document.querySelector('.feed');
const labels={potential_impact:'POTENTIAL IMPACT',review_required:'REVIEW REQUIRED',no_clear_impact:'NO CLEAR IMPACT'};
const domains={listing_rules:'Listing rules',market_infrastructure:'Market infrastructure',licensing_benchmark:'Licensing & benchmarks',enforcement:'Enforcement',prudential:'Prudential',other_regulatory:'Other regulatory',unclear:'Unclear'};
function eventCard(e,selected){const date=new Date(`${e.publication_date}T00:00:00`).toLocaleDateString('en-GB',{day:'2-digit',month:'short'}).toUpperCase();const kind=e.detection==='observed_current_release'?'Recent official release':'New publication';return `<button class="event ${selected?'selected':''}" data-url="${e.official_url}"><div class="event-top"><span class="tag high">${labels[e.impact_status]||'REVIEW'}</span><time>${date}</time></div><h3>${e.title}</h3><p>${kind} · ${e.change_type.replace('_',' ')} · ${domains[e.regulatory_domain]||e.regulatory_domain}</p><div class="meta">${e.source_label} <b>↗</b></div></button>`}
function show(e){document.querySelectorAll('.event').forEach(x=>x.classList.toggle('selected',x.dataset.url===e.official_url));const kind=e.detection==='observed_current_release'?'Recent official release':'New official publication',evidence=e.evidence.filter(q=>!/[一-鿿]/.test(q));detail.innerHTML=`<div class="detail-head"><div><span class="tag high">${labels[e.impact_status]||'REVIEW'}</span><h2>${e.title}</h2><p class="date">Published ${e.publication_date} · Human review required</p></div><a href="${e.official_url}" target="_blank" rel="noreferrer">Open official source ↗</a></div><div class="facts"><div><small>Domain</small><b>${domains[e.regulatory_domain]||e.regulatory_domain}</b></div><div><small>AI triage</small><b>${labels[e.impact_status]||'REVIEW'}</b></div><div><small>Status</small><b>Evidence retained</b></div></div><h3>AI agent preliminary triage</h3><p>${e.summary||'Summary unavailable.'}</p><h3>Monitor classification</h3><p>${kind} · ${e.change_type.replace('_',' ')}</p><div class="evidence"><small>OFFICIAL EVIDENCE · ${e.source_id}</small><ul>${evidence.map(q=>`<li>${q}</li>`).join('')}</ul><p><b>Human review required.</b> AI triage is not a legal or business conclusion.</p></div>`}
function load(items,run={}){const title=feed.querySelector('.section-title');feed.innerHTML='';feed.append(title);items.forEach((e,i)=>feed.insertAdjacentHTML('beforeend',eventCard(e,i===0)));show(items[0]);document.querySelectorAll('.event').forEach(x=>x.onclick=()=>show(items.find(e=>e.official_url===x.dataset.url)));if(run.generated_at)document.querySelector('.run').innerHTML=`<span></span><b>Last run</b><br>${new Date(run.generated_at).toLocaleString('en-GB',{dateStyle:'medium',timeStyle:'short'})} HKT<br><em>${run.sources_checked||1} source checked · AI triage enabled</em>`}
async function hydrate(){try{const r=await fetch('data/latest-run.json');if(!r.ok)throw Error();const run=await r.json();load(run.items?.length?run.items:[fallback],run)}catch{load([fallback])}}
async function hydrateSources(){try{const r=await fetch('data/hk-update-source-catalog.json');if(!r.ok)throw Error();const c=await r.json(),table=document.querySelector('.source-table');table.innerHTML=`<div class="source-head"><p class="eyebrow">ACTIVATED SOURCE REGISTRY</p><h2>Hong Kong update-source catalog</h2><p>${c.summary.active_verified} verified live source · ${c.summary.profile_required} sources awaiting a validated collector.</p></div><div class="tr th"><span>Source ID</span><span>Authority / endpoint</span><span>Route</span><span>Status</span></div>`+c.sources.map(s=>`<div class="tr"><code>${s.source_id}</code><div><b>${s.authority}</b><small>${s.url}</small></div><span>${s.access_pattern}</span><span class="status">${s.alert_eligible?'Active':'Profile required'}</span></div>`).join('')}catch{}}
document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>{document.querySelectorAll('nav button').forEach(x=>x.classList.remove('active'));b.classList.add('active');document.querySelectorAll('.view').forEach(x=>x.classList.add('hidden'));document.querySelector('#'+b.dataset.view).classList.remove('hidden');document.querySelector('#page-title').textContent={monitor:'This week’s changes',sources:'Monitoring sources',method:'Validation workflow'}[b.dataset.view]});
document.querySelector('[data-view="sources"]').addEventListener('click',hydrateSources);
document.querySelector('#run').onclick=async()=>{const t=document.querySelector('#toast');t.textContent='Refreshing the latest published monitor results…';t.classList.add('show');await hydrate();t.textContent='Latest published results loaded';setTimeout(()=>t.classList.remove('show'),3000)};hydrate();
